// product/scripts/vendor.mjs
// Copies the runtime libraries out of node_modules into the source tree so the
// browser imports are plain relative paths: no import map, no bare specifier,
// no CDN. Run `npm run vendor` after any dependency change.
import { cp, mkdir, readFile, rm, writeFile } from 'node:fs/promises';
import { existsSync } from 'node:fs';
import { dirname, join, relative } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const abs = path => join(root, path);
const rel = path => relative(root, path) || '.';

const targets = [
  [
    'node_modules/@huggingface/transformers/dist', 'transformers',
    // The entry module, plus the ONNX runtime files it loads from wasmPaths.
    ['transformers.min.js', 'ort-wasm-simd-threaded.jsep.mjs', 'ort-wasm-simd-threaded.jsep.wasm']
  ],
  ['node_modules/@mlc-ai/web-llm/lib', 'web-llm', ['index.js']]
];

// Source maps and type declarations are never fetched by the browser; keeping
// them would roughly double what `src/vendor` costs in the repository.
const isRuntimeFile = source => !/\.(map|d\.ts)$/.test(source);

for (const [from, , required] of targets) {
  if (!existsSync(abs(from))) throw new Error(`missing ${from}; run npm install first`);
  for (const entry of required) {
    if (!existsSync(join(abs(from), entry))) {
      throw new Error(`missing ${from}/${entry}; the package layout or import path changed`);
    }
  }
}

// A stripped map leaves a dangling comment that shows as a 404 in devtools.
async function stripSourceMap(file) {
  const source = await readFile(file, 'utf8');
  const next = source.replace(/\n?\/\/# sourceMappingURL=\S+\s*$/, '');
  if (next !== source) await writeFile(file, next);
}

// Two copies on purpose: `src/vendor` makes dev and e2e imports resolve exactly
// as they do in `dist/vendor` after a build, with no import map on the host page.
// The root `vendor/` copy is the published artefact folder and is gitignored.
for (const target of ['vendor', 'src/vendor']) {
  for (const [from, name, required] of targets) {
    const dest = abs(`${target}/${name}`);
    await rm(dest, { recursive: true, force: true });
    await mkdir(dest, { recursive: true });
    await cp(abs(from), dest, { recursive: true, filter: isRuntimeFile });
    for (const entry of required) {
      if (!existsSync(join(dest, entry))) {
        throw new Error(`vendor: ${rel(dest)}/${entry} missing after copy`);
      }
    }
    for (const entry of required) {
      if (entry.endsWith('.js')) await stripSourceMap(join(dest, entry));
    }
  }
}

await writeFile(abs('vendor/README.md'),
  'Vendored runtime libraries. Versions are pinned in package.json.\n' +
  'transformers.js: Apache-2.0. WebLLM: Apache-2.0.\n' +
  '\n' +
  'Generated by scripts/vendor.mjs from node_modules; do not edit by hand.\n' +
  'Only runtime files are copied (source maps and .d.ts files are skipped,\n' +
  'and the sourceMappingURL comments are stripped).\n' +
  'src/vendor is the committed copy that dist/vendor is built from.\n');

console.log('vendor: done');
